151	func convertUserSettingFromStore(storeSetting *storepb.UserSetting, user *store.User, key storepb.UserSetting_Key) *v1pb.UserSetting {
152		if storeSetting == nil {
153			// Return default setting if none exists
154			settingKey := convertSettingKeyFromStore(key)
155			setting := &v1pb.UserSetting{
156				Name: fmt.Sprintf("%s/settings/%s", BuildUserName(user.Username), settingKey),
157			}
158	
159			switch key {
160			case storepb.UserSetting_GENERAL:
161				setting.Value = &v1pb.UserSetting_GeneralSetting_{
162					GeneralSetting: getDefaultUserGeneralSetting(),
163				}
164			case storepb.UserSetting_WEBHOOKS:
165				setting.Value = &v1pb.UserSetting_WebhooksSetting_{
166					WebhooksSetting: &v1pb.UserSetting_WebhooksSetting{
167						Webhooks: []*v1pb.UserWebhook{},
168					},
169				}
170			case storepb.UserSetting_TAGS:
171				setting.Value = &v1pb.UserSetting_TagsSetting_{
172					TagsSetting: &v1pb.UserSetting_TagsSetting{Tags: map[string]*v1pb.UserSetting_TagMetadata{}},
173				}
174			default:
175				return nil
176			}
177			return setting
178		}
179	
180		settingKey := convertSettingKeyFromStore(storeSetting.Key)
181		setting := &v1pb.UserSetting{
182			Name: fmt.Sprintf("%s/settings/%s", BuildUserName(user.Username), settingKey),
183		}
184	
185		switch storeSetting.Key {
186		case storepb.UserSetting_GENERAL:
187			if general := storeSetting.GetGeneral(); general != nil {
188				setting.Value = &v1pb.UserSetting_GeneralSetting_{
189					GeneralSetting: &v1pb.UserSetting_GeneralSetting{
190						Locale:         general.Locale,
