192						Theme:          general.Theme,
193					},
194				}
195			} else {
196				setting.Value = &v1pb.UserSetting_GeneralSetting_{
197					GeneralSetting: getDefaultUserGeneralSetting(),
198				}
199			}
200		case storepb.UserSetting_WEBHOOKS:
201			webhooks := storeSetting.GetWebhooks()
202			apiWebhooks := make([]*v1pb.UserWebhook, 0)
203			if webhooks != nil {
204				apiWebhooks = make([]*v1pb.UserWebhook, 0, len(webhooks.Webhooks))
205				for _, webhook := range webhooks.Webhooks {
206					apiWebhook := &v1pb.UserWebhook{
