286	// Hook to fetch multiple users by usernames (returns Map<username, User>)
287	export function useUsersByUsernames(usernames: string[], options?: { enabled?: boolean }) {
288	  const enabled = (options?.enabled ?? true) && usernames.length > 0;
289	  const uniqueUsernames = Array.from(new Set(usernames));
290	
291	  return useQuery({
292	    queryKey: userKeys.byUsernames(uniqueUsernames),
293	    queryFn: async () => {
294	      const batches = [];
295	      for (let i = 0; i < uniqueUsernames.length; i += BATCH_GET_USERS_LIMIT) {
296	        batches.push(uniqueUsernames.slice(i, i + BATCH_GET_USERS_LIMIT));
297	      }
298	
299	      const responses = await Promise.all(batches.map((batch) => userServiceClient.batchGetUsers({ usernames: batch })));
300	      const usersByUsername = new Map(responses.flatMap((response) => response.users).map((user) => [user.username, user] as const));
301	
302	      const userMap = new Map<string, User | undefined>();
303	      for (const username of uniqueUsernames) {
304	        userMap.set(username, usersByUsername.get(username));
305	      }
306	      return userMap;
307	    },
308	    enabled,
309	    staleTime: 1000 * 60 * 5,
310	  });
311	}
